func (a *app) analyze(sentence string) {
	a.print(fmt.Sprintf("Sentença: %s\n\n", a.colors.paint(styleBold, sentence)))
	result := ll1.Parse(a.table, sentence)

	a.print("Tokens:\n")
	var tokenRows [][]string
	for _, token := range result.Tokens {
		tokenRows = append(tokenRows, []string{token.Kind, token.Lexeme, strconv.Itoa(token.Pos)})
	}
	if len(tokenRows) == 0 {
		a.print("  (nenhum token reconhecido)\n")
	} else {
		a.print(table(a.colors, []string{"Token", "Lexema", "Posição"}, tokenRows, nil))
	}

	a.print("\nPassos da análise (topo da pilha à direita):\n")
	const actionColumn = 3
	var stepRows [][]string
	for _, step := range result.Steps {
		stepRows = append(stepRows, []string{
			strconv.Itoa(step.Number),
			strings.Join(step.Stack, " "),
			strings.Join(step.Input, " "),
			step.Action,
		})
	}
	a.print(table(a.colors, []string{"Passo", "Pilha", "Entrada", "Ação"}, stepRows,
		func(_, column int, text string) string {
			switch {
			case column != actionColumn:
				return ""
			case text == ll1.ActionAccept:
				return styleGood
			case strings.HasPrefix(text, ll1.ErrorPrefix):
				return styleBad
			}
			return ""
		}))

	style := styleBad
// … (+5 linhas)

func (a *app) generateInvalid() bool {
	a.section("GERAR SENTENÇA INVÁLIDA")
	a.analyze(ll1.GenerateInvalid(a.grammar, a.rng))
	return true
}

func (a *app) generateValid() bool {
	a.section("GERAR SENTENÇA VÁLIDA")
	a.analyze(ll1.Generate(a.grammar, a.rng, generatedMaxDepth))
	return true
}

func (a *app) print(text string) {
	fmt.Fprint(a.out, text)
}

func (a *app) printMenu() {
	a.print("\n" + a.colors.paint(styleTitle, "MENU") + "\n")
	for _, option := range menu {
		a.print(fmt.Sprintf("  %s  %s\n", a.colors.paint(styleBold, option.key), option.label))
	}
	a.print(fmt.Sprintf("  %s  %s\n\n", a.colors.paint(styleBold, exitKey), "Sair"))
}

func (a *app) productionList() string {
	var sb strings.Builder
	for _, p := range a.grammar.Productions {
		sb.WriteString(fmt.Sprintf("  %2d. %s\n", p.Number, p))
	}
	return sb.String()
}

func (a *app) readLine(prompt string) (string, bool) {
	a.print(prompt)
	if !a.in.Scan() {
		return "", false
	}
	// Keep inner and leading spaces so token positions match what was typed.
	return strings.TrimRight(a.in.Text(), "\r"), true
}

func (a *app) section(title string) {
	a.print("\n" + box(a.colors, title) + "\n")
}

func (a *app) showSets() bool {
	a.section("CONJUNTOS FIRST E FOLLOW")
	first, follow := a.grammar.First(), a.grammar.Follow()
	var rows [][]string
	for _, nt := range a.grammar.NonTerminals {
		rows = append(rows, []string{nt, setText(first[nt]), setText(follow[nt])})
	}
	a.print(table(a.colors, []string{"Não terminal", "FIRST", "FOLLOW"}, rows, nil))
	return true
}

func (a *app) showTable() bool {
	a.section("TABELA DE PARSING LL(1)")
	headers := append([]string{"M"}, a.table.Columns...)
	var rows [][]string
	for _, nt := range a.grammar.NonTerminals {
		row := []string{nt}
		for _, column := range a.table.Columns {
			cell := emptyCell
			if number, ok := a.table.Cells[nt][column]; ok {
				cell = strconv.Itoa(number)
			}
			row = append(row, cell)
		}
		rows = append(rows, row)
	}
	a.print(table(a.colors, headers, rows, nil))
	a.print("Células vazias indicam erro sintático.\n")
	if len(a.table.Conflicts) == 0 {
		a.print("Nenhum conflito: a gramática é LL(1).\n\n")
	} else {
		a.print(a.colors.paint(styleBad, strings.Join(a.table.Conflicts, "\n")) + "\n\n")
	}
	a.print(a.productionList())
	return true
}

func (a *app) typeSentence() bool {
	a.section("DIGITAR SENTENÇA")
	sentence, ok := a.readLine("Digite a sentença: ")
	if !ok {
		return false
	}
	a.analyze(sentence)
	return true
}

func (a *app) waitForEnter() bool {
	_, ok := a.readLine("\n" + a.colors.paint(styleDim, "Pressione Enter para voltar ao menu"))
	return ok
}

func box(p palette, lines ...string) string {
	width := 0
	for _, line := range lines {
		width = max(width, utf8.RuneCountInString(line))
	}
	var sb strings.Builder
	sb.WriteString("╔" + strings.Repeat("═", width+4) + "╗\n")
	for _, line := range lines {
		sb.WriteString("║  " + p.paint(styleTitle, pad(line, width)) + "  ║\n")
	}
	sb.WriteString("╚" + strings.Repeat("═", width+4) + "╝\n")
	return sb.String()
}

func findOption(key string) (menuOption, bool) {
	for _, option := range menu {
		if option.key == key {
			return option, true
		}
	}
	return menuOption{}, false
}

func main() {
	colors := os.Getenv("NO_COLOR") == "" && prepareConsole()
	rng := rand.New(rand.NewSource(time.Now().UnixNano()))
	run(os.Stdin, os.Stdout, colors, rng)
}

func pad(text string, width int) string {
	return text + strings.Repeat(" ", width-utf8.RuneCountInString(text))
}

func (p palette) paint(style, text string) string {
	if !p.enabled || text == "" {
		return text
	}
	return style + text + styleReset
}

func prepareConsole() bool {
	info, err := os.Stdout.Stat()
	return err == nil && info.Mode()&os.ModeCharDevice != 0
}

func prepareConsole() bool {
	handle := os.Stdout.Fd()
	var mode uint32
	if ok, _, _ := procGetConsoleMode.Call(handle, uintptr(unsafe.Pointer(&mode))); ok == 0 {
		return false
	}
	ok, _, _ := procSetConsoleMode.Call(handle, uintptr(mode|enableVirtualTerminalProcessing))
	return ok != 0
}

func run(in io.Reader, out io.Writer, colors bool, rng *rand.Rand) {
	grammar := ll1.Default()
	a := &app{
		grammar: grammar,
		table:   ll1.BuildTable(grammar),
		rng:     rng,
		in:      bufio.NewScanner(in),
		out:     out,
		colors:  palette{enabled: colors},
	}
	a.print(box(a.colors,
		"ANALISADOR SINTÁTICO LL(1)",
		"Preditivo tabular (não recursivo)"))
	for {
		a.printMenu()
		choice, ok := a.readLine("Escolha uma opção: ")
		choice = strings.TrimSpace(choice)
		if !ok || choice == exitKey {
			a.print("\nAté logo!\n")
			return
		}
		option, found := findOption(choice)
		if !found {
			a.print(a.colors.paint(styleBad, "Opção inválida.") + "\n")
			continue
		}
		if !option.action(a) || !a.waitForEnter() {
			a.print("\nAté logo!\n")
			return
		}
	}
}

func setText(symbols []string) string {
	return "{ " + strings.Join(symbols, ", ") + " }"
}

func table(p palette, headers []string, rows [][]string, style cellStyle) string {
	widths := make([]int, len(headers))
	for i, h := range headers {
		widths[i] = utf8.RuneCountInString(h)
	}
	for _, row := range rows {
		for i, cell := range row {
			widths[i] = max(widths[i], utf8.RuneCountInString(cell))
		}
	}
	border := func(left, middle, right string) string {
		parts := make([]string, len(widths))
		for i, w := range widths {
			parts[i] = strings.Repeat("─", w+2)
		}
		return left + strings.Join(parts, middle) + right + "\n"
	}
	line := func(cells []string, paint func(column int, text string) string) string {
		parts := make([]string, len(widths))
		for i, w := range widths {
			parts[i] = " " + paint(i, pad(cells[i], w)) + " "
		}
		return "│" + strings.Join(parts, "│") + "│\n"
	}

	var sb strings.Builder
	sb.WriteString(border("┌", "┬", "┐"))
	sb.WriteString(line(headers, func(_ int, text string) string { return p.paint(styleBold, text) }))
	sb.WriteString(border("├", "┼", "┤"))
	for r, row := range rows {
		sb.WriteString(line(row, func(column int, text string) string {
			if style == nil {
				return text
			}
			return p.paint(style(r, column, row[column]), text)
		}))
	}
	sb.WriteString(border("└", "┴", "┘"))
	return sb.String()
}

func buildGraph(root string) (*Graph, error) {
	module, err := readModulePath(filepath.Join(root, "go.mod"))
	if err != nil {
		return nil, err
	}
	b := &builder{
		module:        module,
		fset:          token.NewFileSet(),
		nodes:         map[string]*Node{},
		edges:         map[Edge]bool{},
		funcsByDir:    map[string]map[string]string{},
		methodsByName: map[string][]string{},
		declIDs:       map[*ast.FuncDecl]string{},
		sources:       map[string][]string{},
	}
	if err := b.parseTree(root); err != nil {
		return nil, err
	}
	b.declare()
	b.link()
	return b.result(), nil
}

func (b *builder) addEdge(from, to, kind string) {
	if from != "" && to != "" && from != to {
		b.edges[Edge{From: from, To: to, Kind: kind}] = true
	}
}

func (b *builder) collectCalls(pf *parsedFile, caller string, body *ast.BlockStmt) {
	// Selector names and struct-literal keys look like identifiers but are not references.
	skipIdents := map[*ast.Ident]bool{}
	ast.Inspect(body, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.SelectorExpr:
			skipIdents[x.Sel] = true
		case *ast.KeyValueExpr:
			if key, ok := x.Key.(*ast.Ident); ok {
				skipIdents[key] = true
			}
		}
		return true
	})

	ast.Inspect(body, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.CallExpr:
			if sel, ok := x.Fun.(*ast.SelectorExpr); ok {
				b.addEdge(caller, b.resolveSelector(pf, sel), edgeCalls)
			}
		case *ast.Ident:
			// Covers direct calls and functions passed as values; Obj is set for locals.
			if !skipIdents[x] && (x.Obj == nil || x.Obj.Kind == ast.Fun) {
				b.addEdge(caller, b.funcsByDir[pf.dir][x.Name], edgeCalls)
			}
		}
		return true
	})
}

func (b *builder) declare() {
	for _, pf := range b.files {
		pkgID := packageID(pf.dir)
		pkg := b.nodes[pkgID]
		if pkg == nil {
			pkg = &Node{ID: pkgID, Label: b.packageLabel(pf.dir), Kind: kindPackage, Package: pf.dir,
				Signature: "package " + pf.file.Name.Name}
			b.nodes[pkgID] = pkg
		}
		if pkg.Doc == "" {
			pkg.Doc = firstParagraph(pf.file.Doc)
		}

		fileID := "file:" + pf.rel
		b.nodes[fileID] = &Node{ID: fileID, Label: path.Base(pf.rel), Kind: kindFile, Package: pf.dir,
			File: pf.rel, Line: 1, Signature: importSummary(pf.file)}
		b.addEdge(pkgID, fileID, edgeContains)

		pf.imports = map[string]string{}
		for _, spec := range pf.file.Imports {
			b.declareImport(pf, pkgID, spec)
		}

		for _, decl := range pf.file.Decls {
			switch d := decl.(type) {
			case *ast.GenDecl:
				b.declareTypes(pf, fileID, d)
			case *ast.FuncDecl:
				b.declareFunc(pf, fileID, d)
			}
		}
	}
}

func (b *builder) declareFunc(pf *parsedFile, fileID string, d *ast.FuncDecl) {
	line := b.fset.Position(d.Pos()).Line
	end := b.fset.Position(d.End()).Line
	kind, label, prefix := kindFunc, d.Name.Name, "func:"+pf.dir+"."
	recv := receiverName(d)
	if recv != "" {
		kind, label, prefix = kindMethod, recv+"."+d.Name.Name, "func:"+pf.dir+"."+recv+"."
	}
	id := b.uniqueID(prefix+d.Name.Name, line)
	b.nodes[id] = &Node{ID: id, Label: label, Kind: kind, Package: pf.dir, File: pf.rel, Line: line,
		Doc: firstParagraph(d.Doc), Signature: signature(d), Code: b.snippet(pf.rel, line, end)}
	b.declIDs[d] = id
	b.addEdge(fileID, id, edgeContains)
	pf.decls = append(pf.decls, d)

	if recv == "" {
		if b.funcsByDir[pf.dir] == nil {
			b.funcsByDir[pf.dir] = map[string]string{}
		}
		b.funcsByDir[pf.dir][d.Name.Name] = id
		return
	}
	b.methodsByName[d.Name.Name] = append(b.methodsByName[d.Name.Name], id)
	b.addEdge("type:"+pf.dir+"."+recv, id, edgeMethod)
}

func (b *builder) declareImport(pf *parsedFile, pkgID string, spec *ast.ImportSpec) {
	importPath := strings.Trim(spec.Path.Value, `"`)
	local := path.Base(importPath)
	if spec.Name != nil {
		local = spec.Name.Name
	}
	if local == "_" || local == "." {
		return
	}
	dir := ""
	switch {
	case importPath == b.module:
		dir = rootDir
	case strings.HasPrefix(importPath, b.module+"/"):
		dir = strings.TrimPrefix(importPath, b.module+"/")
	}
	pf.imports[local] = dir
	if dir != "" {
		b.addEdge(pkgID, packageID(dir), edgeImports)
	}
}

func (b *builder) declareTypes(pf *parsedFile, fileID string, d *ast.GenDecl) {
	if d.Tok != token.TYPE {
		return
	}
	for _, spec := range d.Specs {
		ts := spec.(*ast.TypeSpec)
		line := b.fset.Position(ts.Pos()).Line
		id := b.uniqueID("type:"+pf.dir+"."+ts.Name.Name, line)
		doc := ts.Doc
		if doc == nil && len(d.Specs) == 1 {
			doc = d.Doc
		}
		end := b.fset.Position(ts.End()).Line
		b.nodes[id] = &Node{ID: id, Label: ts.Name.Name, Kind: kindType, Package: pf.dir, File: pf.rel,
			Line: line, Doc: firstParagraph(doc), Signature: typeSignature(ts), Code: b.snippet(pf.rel, line, end)}
		b.addEdge(fileID, id, edgeContains)
	}
}

func (b *builder) link() {
	for _, pf := range b.files {
		for _, d := range pf.decls {
			if d.Body != nil {
				b.collectCalls(pf, b.declIDs[d], d.Body)
			}
		}
	}
}

func (b *builder) packageLabel(dir string) string {
	if dir == rootDir {
		return path.Base(b.module)
	}
	return dir
}

func (b *builder) parseTree(root string) error {
	return filepath.WalkDir(root, func(p string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		name := entry.Name()
		if entry.IsDir() {
			if p != root && (strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_") || skippedDirs[name]) {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			return nil
		}
		rel, err := filepath.Rel(root, p)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		data, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		file, err := parser.ParseFile(b.fset, rel, data, parser.ParseComments)
		if err != nil {
			return err
		}
		dir := path.Dir(rel)
		b.sources[rel] = strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
		b.files = append(b.files, &parsedFile{dir: dir, rel: rel, file: file})
		return nil
	})
}

func (b *builder) resolveSelector(pf *parsedFile, sel *ast.SelectorExpr) string {
	if x, ok := sel.X.(*ast.Ident); ok && x.Obj == nil {
		if dir, imported := pf.imports[x.Name]; imported {
			if dir == "" {
				return ""
			}
			return b.funcsByDir[dir][sel.Sel.Name]
		}
	}
	if ids := b.methodsByName[sel.Sel.Name]; len(ids) == 1 {
		return ids[0]
	}
	return ""
}

func (b *builder) result() *Graph {
	graph := &Graph{Module: b.module, Nodes: []Node{}, Edges: []Edge{}}
	for _, n := range b.nodes {
		graph.Nodes = append(graph.Nodes, *n)
	}
	for e := range b.edges {
		if b.nodes[e.From] != nil && b.nodes[e.To] != nil {
			graph.Edges = append(graph.Edges, e)
		}
	}
	sort.Slice(graph.Nodes, func(i, j int) bool { return graph.Nodes[i].ID < graph.Nodes[j].ID })
	sort.Slice(graph.Edges, func(i, j int) bool {
		a, c := graph.Edges[i], graph.Edges[j]
		if a.From != c.From {
			return a.From < c.From
		}
		if a.To != c.To {
			return a.To < c.To
		}
		return a.Kind < c.Kind
	})
	return graph
}

func (b *builder) snippet(file string, start, end int) string {
	lines := b.sources[file]
	if start < 1 || start > len(lines) {
		return ""
	}
	if end > len(lines) {
		end = len(lines)
	}
	total := end - start + 1
	if total > maxSnippetLines {
		cut := lines[start-1 : start-1+maxSnippetLines]
		return strings.Join(cut, "\n") + fmt.Sprintf("\n// … (+%d linhas)", total-maxSnippetLines)
	}
	return strings.Join(lines[start-1:end], "\n")
}

func (b *builder) uniqueID(id string, line int) string {
	if _, taken := b.nodes[id]; taken {
		return fmt.Sprintf("%s:%d", id, line)
	}
	return id
}

func firstParagraph(doc *ast.CommentGroup) string {
	if doc == nil {
		return ""
	}
	// A doc comment's first line is often cut mid-sentence, so keep the whole first paragraph.
	text := strings.TrimSpace(doc.Text())
	if i := strings.Index(text, "\n\n"); i >= 0 {
		text = text[:i]
	}
	return strings.Join(strings.Fields(text), " ")
}

func importSummary(file *ast.File) string {
	var paths []string
	for _, spec := range file.Imports {
		paths = append(paths, strings.Trim(spec.Path.Value, `"`))
	}
	if len(paths) == 0 {
		return ""
	}
	return "import " + strings.Join(paths, ", ")
}

