func printNode(node any) string {
	var buf bytes.Buffer
	if err := printer.Fprint(&buf, token.NewFileSet(), node); err != nil {
		return ""
	}
	return buf.String()
}

func readModulePath(goMod string) (string, error) {
	data, err := os.ReadFile(goMod)
	if err != nil {
		return "", err
	}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, modulePrefix) {
			return strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, modulePrefix)), `"`), nil
		}
	}
	return "", fmt.Errorf("no module line in %s", goMod)
}

func receiverName(d *ast.FuncDecl) string {
	if d.Recv == nil || len(d.Recv.List) == 0 {
		return ""
	}
	expr := d.Recv.List[0].Type
	for {
		switch t := expr.(type) {
		case *ast.StarExpr:
			expr = t.X
		case *ast.IndexExpr:
			expr = t.X
		case *ast.IndexListExpr:
			expr = t.X
		case *ast.ParenExpr:
			expr = t.X
		case *ast.Ident:
			return t.Name
		default:
			return ""
		}
	}
}

func signature(d *ast.FuncDecl) string {
	header := *d
	header.Body = nil
	header.Doc = nil
	sig := strings.Join(strings.Fields(printNode(&header)), " ")
	if len(sig) > maxSignatureLen {
		sig = sig[:maxSignatureLen] + "…"
	}
	return sig
}

func typeSignature(ts *ast.TypeSpec) string {
	switch t := ts.Type.(type) {
	case *ast.StructType:
		return "type " + ts.Name.Name + " struct"
	case *ast.InterfaceType:
		return "type " + ts.Name.Name + " interface"
	default:
		return "type " + ts.Name.Name + " " + printNode(t)
	}
}

func consultedCell(step ll1.Step) *cellRefJSON {
	if len(step.Stack) == 0 || len(step.Input) == 0 {
		return nil
	}
	top := step.Stack[len(step.Stack)-1]
	if !grammar.IsNonTerminal(top) {
		return nil
	}
	if _, ok := table.Production(top, step.Input[0]); !ok {
		return nil
	}
	return &cellRefJSON{NonTerminal: top, Column: step.Input[0]}
}

func grammarValue() any {
	out := grammarJSON{
		Start:        grammar.Start,
		Grouped:      strings.Split(strings.TrimSpace(grammar.String()), "\n"),
		Terminals:    grammar.Terminals,
		NonTerminals: grammar.NonTerminals,
	}
	for _, production := range grammar.Productions {
		out.Productions = append(out.Productions, productionJSON{
			Number: production.Number,
			Head:   production.Head,
			Body:   production.Body,
			Text:   production.String(),
		})
	}
	return toJSON(out)
}

func main() {
	api := map[string]any{
		"grammar": js.FuncOf(func(js.Value, []js.Value) any { return grammarValue() }),
		"sets":    js.FuncOf(func(js.Value, []js.Value) any { return setsValue() }),
		"table":   js.FuncOf(func(js.Value, []js.Value) any { return tableValue() }),
		"parse": js.FuncOf(func(_ js.Value, args []js.Value) any {
			input := ""
			if len(args) > 0 {
				input = args[0].String()
			}
			return parseValue(input)
		}),
		"generate": js.FuncOf(func(js.Value, []js.Value) any {
			return ll1.Generate(grammar, rng, maxGenerateDepth)
		}),
		"generateInvalid": js.FuncOf(func(js.Value, []js.Value) any {
			return ll1.GenerateInvalid(grammar, rng)
		}),
	}
	js.Global().Set("ll1", js.ValueOf(api))
	select {}
}

func parseValue(input string) any {
	result := ll1.Parse(table, input)
	out := resultJSON{Accepted: result.Accepted, Message: result.Message, Tokens: []tokenJSON{}, Steps: []stepJSON{}}
	for _, token := range result.Tokens {
		out.Tokens = append(out.Tokens, tokenJSON{token.Kind, token.Lexeme, token.Pos})
	}
	for _, step := range result.Steps {
		out.Steps = append(out.Steps, stepJSON{step.Number, step.Stack, step.Input, step.Action, consultedCell(step)})
	}
	return toJSON(out)
}

func setsValue() any {
	first, follow := grammar.First(), grammar.Follow()
	rows := []setsRowJSON{}
	for _, nonTerminal := range grammar.NonTerminals {
		rows = append(rows, setsRowJSON{nonTerminal, first[nonTerminal], follow[nonTerminal]})
	}
	return toJSON(rows)
}

func tableValue() any {
	out := tableJSON{Columns: table.Columns, Conflicts: append([]string{}, table.Conflicts...), Rows: []tableRowJSON{}}
	for _, nonTerminal := range grammar.NonTerminals {
		row := tableRowJSON{NonTerminal: nonTerminal}
		for _, column := range table.Columns {
			cell := tableCellJSON{Column: column}
			if production, ok := table.Production(nonTerminal, column); ok {
				cell.Number, cell.Text = production.Number, production.String()
			}
			row.Cells = append(row.Cells, cell)
		}
		out.Rows = append(out.Rows, row)
	}
	return toJSON(out)
}

func toJSON(value any) any {
	encoded, err := json.Marshal(value)
	if err != nil {
		return `{"error":"` + err.Error() + `"}`
	}
	return string(encoded)
}

func BuildTable(g *Grammar) *Table {
	t := &Table{
		Grammar: g,
		Columns: append(append([]string{}, g.Terminals...), EndMarker),
		Cells:   make(map[string]map[string]int, len(g.NonTerminals)),
	}
	for _, nt := range g.NonTerminals {
		t.Cells[nt] = map[string]int{}
	}
	first := g.firstSets()
	follow := g.followSets(first)
	for _, p := range g.Productions {
		bodyFirst := g.firstOfSequence(first, p.Body)
		for _, column := range t.Columns {
			if bodyFirst[column] || (bodyFirst[Epsilon] && follow[p.Head][column]) {
				t.place(p, column)
			}
		}
	}
	return t
}

func Default() *Grammar {
	bodies := []struct {
		head string
		body string
	}{
		{"E", "T E'"},
		{"E'", "+ T E'"},
		{"E'", "- T E'"},
		{"E'", Epsilon},
		{"T", "F T'"},
		{"T'", "* F T'"},
		{"T'", "/ F T'"},
		{"T'", Epsilon},
		{"F", "( E )"},
		{"F", TerminalID},
		{"F", TerminalNum},
	}
	g := &Grammar{
		Start:        "E",
		NonTerminals: []string{"E", "E'", "T", "T'", "F"},
		Terminals:    []string{TerminalID, TerminalNum, "+", "-", "*", "/", "(", ")"},
	}
	for i, b := range bodies {
		g.Productions = append(g.Productions, Production{
			Number: i + 1,
			Head:   b.head,
			Body:   strings.Fields(b.body),
		})
	}
	return g
}

func Generate(g *Grammar, rng *rand.Rand, maxDepth int) string {
	heights := g.productionHeights()
	var lexemes []string
	var expand func(symbol string, depth int)
	expand = func(symbol string, depth int) {
		if !g.IsNonTerminal(symbol) {
			lexemes = append(lexemes, lexemeFor(symbol, rng))
			return
		}
		p := chooseProduction(g.ProductionsOf(symbol), heights, rng, depth >= maxDepth)
		if p.IsEmpty() {
			return
		}
		for _, child := range p.Body {
			expand(child, depth+1)
		}
	}
	expand(g.Start, 0)
	return strings.Join(lexemes, " ")
}

func GenerateInvalid(g *Grammar, rng *rand.Rand) string {
	table := BuildTable(g)
	for {
		lexemes := strings.Fields(Generate(g, rng, invalidBaseDepth))
		candidate := strings.Join(mutate(lexemes, rng), " ")
		if !Parse(table, candidate).Accepted {
			return candidate
		}
	}
}

func (g *Grammar) First() map[string][]string {
	first := g.firstSets()
	result := make(map[string][]string, len(first))
	for nt, set := range first {
		result[nt] = g.ordered(set, Epsilon)
	}
	return result
}

func (g *Grammar) FirstOfSequence(seq []string) []string {
	return g.ordered(g.firstOfSequence(g.firstSets(), seq), Epsilon)
}

func (g *Grammar) Follow() map[string][]string {
	follow := g.followSets(g.firstSets())
	result := make(map[string][]string, len(follow))
	for nt, set := range follow {
		result[nt] = g.ordered(set, EndMarker)
	}
	return result
}

func (g *Grammar) IsNonTerminal(s string) bool {
	return contains(g.NonTerminals, s)
}

func (g *Grammar) IsTerminal(s string) bool {
	return contains(g.Terminals, s)
}

func (g *Grammar) ProductionsOf(nonTerminal string) []Production {
	var result []Production
	for _, p := range g.Productions {
		if p.Head == nonTerminal {
			result = append(result, p)
		}
	}
	return result
}

func (g *Grammar) String() string {
	var sb strings.Builder
	for _, nt := range g.NonTerminals {
		var alternatives []string
		for _, p := range g.ProductionsOf(nt) {
			alternatives = append(alternatives, strings.Join(p.Body, " "))
		}
		sb.WriteString(nt)
		sb.WriteString(Arrow)
		sb.WriteString(strings.Join(alternatives, " | "))
		sb.WriteString("\n")
	}
	return sb.String()
}

func (g *Grammar) firstOfSequence(first map[string]symbolSet, seq []string) symbolSet {
	result := symbolSet{}
	for _, symbol := range seq {
		if symbol == Epsilon {
			continue
		}
		if !g.IsNonTerminal(symbol) {
			result[symbol] = true
			return result
		}
		result.addAll(first[symbol], Epsilon)
		if !first[symbol][Epsilon] {
			return result
		}
	}
	// Every symbol can vanish (or the sequence is empty).
	result[Epsilon] = true
	return result
}

func (g *Grammar) firstSets() map[string]symbolSet {
	first := make(map[string]symbolSet, len(g.NonTerminals))
	for _, nt := range g.NonTerminals {
		first[nt] = symbolSet{}
	}
	for changed := true; changed; {
		changed = false
		for _, p := range g.Productions {
			if first[p.Head].addAll(g.firstOfSequence(first, p.Body), "") {
				changed = true
			}
		}
	}
	return first
}

func (g *Grammar) followSets(first map[string]symbolSet) map[string]symbolSet {
	follow := make(map[string]symbolSet, len(g.NonTerminals))
	for _, nt := range g.NonTerminals {
		follow[nt] = symbolSet{}
	}
	follow[g.Start][EndMarker] = true
	for changed := true; changed; {
		changed = false
		for _, p := range g.Productions {
			for i, symbol := range p.Body {
				if !g.IsNonTerminal(symbol) {
					continue
				}
				rest := g.firstOfSequence(first, p.Body[i+1:])
				if follow[symbol].addAll(rest, Epsilon) {
					changed = true
				}
				if rest[Epsilon] && follow[symbol].addAll(follow[p.Head], "") {
					changed = true
				}
			}
		}
	}
	return follow
}

func (g *Grammar) ordered(set symbolSet, extra string) []string {
	result := []string{}
	for _, t := range g.Terminals {
		if set[t] {
			result = append(result, t)
		}
	}
	if set[extra] {
		result = append(result, extra)
	}
	return result
}

func (g *Grammar) productionHeights() map[int]int {
	symbolHeight := map[string]int{}
	for _, nt := range g.NonTerminals {
		symbolHeight[nt] = math.MaxInt
	}
	heightOf := func(p Production) int {
		height := 0
		for _, symbol := range p.Body {
			if h, isNonTerminal := symbolHeight[symbol]; isNonTerminal {
				if h == math.MaxInt {
					return math.MaxInt
				}
				height = max(height, h)
			}
		}
		return height + 1
	}
	for changed := true; changed; {
		changed = false
		for _, p := range g.Productions {
			if h := heightOf(p); h < symbolHeight[p.Head] {
				symbolHeight[p.Head] = h
				changed = true
			}
		}
	}
	heights := make(map[int]int, len(g.Productions))
	for _, p := range g.Productions {
		heights[p.Number] = heightOf(p)
	}
	return heights
}

