func (p Production) IsEmpty() bool {
	return len(p.Body) == 1 && p.Body[0] == Epsilon
}

func (p Production) String() string {
	return p.Head + Arrow + strings.Join(p.Body, " ")
}

func (t *Table) Production(nonTerminal, column string) (Production, bool) {
	number, ok := t.Cells[nonTerminal][column]
	if !ok {
		return Production{}, false
	}
	for _, p := range t.Grammar.Productions {
		if p.Number == number {
			return p, true
		}
	}
	return Production{}, false
}

func (t *Table) place(p Production, column string) {
	row := t.Cells[p.Head]
	if existing, taken := row[column]; taken {
		t.Conflicts = append(t.Conflicts, fmt.Sprintf(
			"Conflito em M[%s, %s]: produções %d e %d", p.Head, column, existing, p.Number))
		return
	}
	row[column] = p.Number
}

func Tokenize(input string) ([]Token, error) {
	runes := []rune(input)
	var tokens []Token
	for i := 0; i < len(runes); {
		r := runes[i]
		start := i
		switch {
		case isSpace(r):
			i++
			continue
		case isLetter(r):
			for i < len(runes) && (isLetter(runes[i]) || isDigit(runes[i])) {
				i++
			}
			tokens = append(tokens, Token{Kind: TerminalID, Lexeme: string(runes[start:i]), Pos: start + 1})
		case isDigit(r):
			for i < len(runes) && isDigit(runes[i]) {
				i++
			}
			tokens = append(tokens, Token{Kind: TerminalNum, Lexeme: string(runes[start:i]), Pos: start + 1})
		case isOperator(r):
			i++
			tokens = append(tokens, Token{Kind: string(r), Lexeme: string(r), Pos: start + 1})
		default:
			return nil, &LexicalError{Char: r, Pos: start + 1}
		}
	}
	tokens = append(tokens, Token{Kind: EndMarker, Lexeme: EndMarker, Pos: len(runes) + 1})
	return tokens, nil
}

func chooseProduction(options []Production, heights map[int]int, rng *rand.Rand, shortest bool) Production {
	if shortest {
		best := math.MaxInt
		var fastest []Production
		for _, p := range options {
			switch h := heights[p.Number]; {
			case h < best:
				best = h
				fastest = []Production{p}
			case h == best:
				fastest = append(fastest, p)
			}
		}
		options = fastest
	}
	return options[rng.Intn(len(options))]
}

func contains(list []string, s string) bool {
	for _, item := range list {
		if item == s {
			return true
		}
	}
	return false
}

func describeSymbol(symbol string) string {
	if symbol == EndMarker {
		return "fim da entrada"
	}
	return "'" + symbol + "'"
}

func insertAt(lexemes []string, i int, lexeme string) []string {
	result := append([]string{}, lexemes[:i]...)
	result = append(result, lexeme)
	return append(result, lexemes[i:]...)
}

func isDigit(r rune) bool {
	return r >= '0' && r <= '9'
}

func isLetter(r rune) bool {
	return r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}

func isOperator(r rune) bool {
	for _, op := range operators {
		if r == op {
			return true
		}
	}
	return false
}

func isSpace(r rune) bool {
	return r == ' ' || r == '\t' || r == '\r' || r == '\n'
}

func kinds(tokens []Token) []string {
	result := make([]string, len(tokens))
	for i, token := range tokens {
		result[i] = token.Kind
	}
	return result
}

func lexemeFor(terminal string, rng *rand.Rand) string {
	switch terminal {
	case TerminalID:
		return identifierLexemes[rng.Intn(len(identifierLexemes))]
	case TerminalNum:
		return strconv.Itoa(rng.Intn(maxNumberLexeme + 1))
	default:
		return terminal
	}
}

func lexicalFailure(start []string, input string, lexErr *LexicalError) Result {
	prefix := string([]rune(input)[:lexErr.Pos-1])
	read, _ := Tokenize(prefix)
	read = read[:len(read)-1] // drop the "$" of the prefix
	remaining := append(kinds(read), string(lexErr.Char), EndMarker)
	step := Step{
		Number: 1,
		Stack:  start,
		Input:  remaining,
		Action: ErrorPrefix + " léxico: " + lexErr.Detail(),
	}
	return Result{
		Message: fmt.Sprintf(messageRejected, lexErr.Error()),
		Tokens:  read,
		Steps:   []Step{step},
	}
}

func matchAction(token Token) string {
	if token.Lexeme == token.Kind {
		return fmt.Sprintf("Casa '%s'", token.Kind)
	}
	return fmt.Sprintf("Casa '%s' (%s)", token.Kind, token.Lexeme)
}

func mutate(lexemes []string, rng *rand.Rand) []string {
	const (
		dropToken = iota
		duplicateOperator
		unbalancedParenthesis
		illegalCharacter
		mutationCount
	)
	switch rng.Intn(mutationCount) {
	case dropToken:
		i := rng.Intn(len(lexemes))
		return append(append([]string{}, lexemes[:i]...), lexemes[i+1:]...)
	case duplicateOperator:
		var operatorIndexes []int
		for i, lexeme := range lexemes {
			if strings.Contains(operators, lexeme) {
				operatorIndexes = append(operatorIndexes, i)
			}
		}
		if len(operatorIndexes) > 0 {
			i := operatorIndexes[rng.Intn(len(operatorIndexes))]
			return insertAt(lexemes, i, lexemes[i])
		}
		return insertAt(lexemes, rng.Intn(len(lexemes)+1), "+")
	case unbalancedParenthesis:
		parenthesis := []string{"(", ")"}[rng.Intn(2)]
		return insertAt(lexemes, rng.Intn(len(lexemes)+1), parenthesis)
	default:
		char := illegalCharacters[rng.Intn(len(illegalCharacters))]
		return insertAt(lexemes, rng.Intn(len(lexemes)+1), char)
	}
}

func reject(result Result, step Step, reason string) Result {
	step.Action = ErrorPrefix + ": " + reason
	result.Steps = append(result.Steps, step)
	result.Message = fmt.Sprintf(messageRejected, reason)
	return result
}

func (s symbolSet) addAll(other symbolSet, skip string) bool {
	grew := false
	for symbol := range other {
		if symbol != skip && !s[symbol] {
			s[symbol] = true
			grew = true
		}
	}
	return grew
}

func unexpected(token Token) string {
	if token.Kind == EndMarker {
		return "fim da entrada inesperado"
	}
	return fmt.Sprintf("token '%s' inesperado na posição %d", token.Lexeme, token.Pos)
}

